var GEOM = (function () {
  function center(n) { return { x: n.x + n.w / 2, y: n.y + n.h / 2 }; }
  // p is inside rect r, q is outside; returns the point where the segment leaves r
  function clipSeg(r, p, q) {
    var dx = q.x - p.x, dy = q.y - p.y, cand = [];
    if (dx > 0) cand.push((r.x + r.w - p.x) / dx); else if (dx < 0) cand.push((r.x - p.x) / dx);
    if (dy > 0) cand.push((r.y + r.h - p.y) / dy); else if (dy < 0) cand.push((r.y - p.y) / dy);
    var t = 1;
    for (var i = 0; i < cand.length; i++) if (cand[i] >= 0 && cand[i] < t) t = cand[i];
    return { x: p.x + dx * t, y: p.y + dy * t };
  }
  function pairKey(a, b) { return a < b ? a + "|" + b : b + "|" + a; }
  // assigns a perpendicular offset to straight edges that share a node pair
  function offsets(edges) {
    var groups = {}, out = {};
    edges.forEach(function (e) {
      if (e.via && e.via.length) return;
      var k = pairKey(e.from, e.to);
      (groups[k] = groups[k] || []).push(e);
    });
    Object.keys(groups).forEach(function (k) {
      var g = groups[k], n = g.length;
      if (n === 1) { out[g[0].id] = { offset: 0, at: 0.5 }; return; }
      var step = n === 2 ? 16 : 14;
      g.forEach(function (e, i) { out[e.id] = { offset: (i - (n - 1) / 2) * step, at: 0.5 + (i - (n - 1) / 2) * 0.22 }; });
    });
    return out;
  }
  function points(nodes, e, offset) {
    var a = nodes[e.from], b = nodes[e.to], ca = center(a), cb = center(b);
    if (e.via && e.via.length) {
      var first = { x: e.via[0][0], y: e.via[0][1] };
      var last = { x: e.via[e.via.length - 1][0], y: e.via[e.via.length - 1][1] };
      var pts = [clipSeg(a, ca, first)];
      e.via.forEach(function (v) { pts.push({ x: v[0], y: v[1] }); });
      pts.push(clipSeg(b, cb, last));
      return pts;
    }
    var c1 = ca, c2 = cb;
    if (offset) {
      // canonical direction so both directions of a pair share one normal
      var canon = e.from < e.to;
      var sx = canon ? ca : cb, tx = canon ? cb : ca;
      var dx = tx.x - sx.x, dy = tx.y - sx.y, L = Math.sqrt(dx * dx + dy * dy) || 1;
      var nx = -dy / L * offset, ny = dx / L * offset;
      c1 = { x: ca.x + nx, y: ca.y + ny }; c2 = { x: cb.x + nx, y: cb.y + ny };
    }
    return [clipSeg(a, c1, c2), clipSeg(b, c2, c1)];
  }
  function midpoint(pts, at) {
    var total = 0, segs = [];
    if (typeof at !== "number") at = 0.5;
    for (var i = 1; i < pts.length; i++) {
      var d = Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y);
      segs.push(d); total += d;
    }
    var half = total * at;
    for (var j = 0; j < segs.length; j++) {
      if (half <= segs[j]) {
        var t = segs[j] ? half / segs[j] : 0;
        return { x: pts[j].x + (pts[j + 1].x - pts[j].x) * t, y: pts[j].y + (pts[j + 1].y - pts[j].y) * t };
      }
      half -= segs[j];
    }
    return pts[pts.length - 1];
  }
  function pathD(pts) {
    return pts.map(function (p, i) { return (i ? "L" : "M") + p.x.toFixed(1) + " " + p.y.toFixed(1); }).join(" ");
  }
  return { center: center, clipSeg: clipSeg, offsets: offsets, points: points, midpoint: midpoint, pathD: pathD };
})();
if (typeof module !== "undefined") module.exports = GEOM;

window.DATASETS = window.DATASETS || {};
window.DATASETS.compass = {
  id: "compass",
  title: "Accessibility Compass",
  short: "Compass instance",
  subtitle: "One real request, Run scan, followed from the browser through every component and back. Arrows 1 to 8 are synchronous, 9 to 22 are the background scan, 23 is the browser polling, 24 to 27 are the other two paths, 28 and 29 are configuration and deployment.",
  sourceUrl: "https://claude.ai/artifact/GGvECip4ZCkvuN63PbjCgk",
  sourceLabel: "Compass field view (document)",
  viewBox: [0, 0, 1190, 945],
  frames: [
    { id: "CLIENT", x: 20, y: 20, w: 250, h: 96, label: "Admin workstation" },
    { id: "HOST", x: 280, y: 20, w: 690, h: 910, label: "TTU server tosmonline0001, one host, Docker Compose", labelPos: "bottom" },
    { id: "EXT", x: 985, y: 295, w: 190, h: 372, label: "External services" },
    { id: "SRC", x: 20, y: 715, w: 250, h: 200, label: "Source and deploy" }
  ],
  readFirst: [
    "Celery is not in this stack. The worksheet names arq (Q2, Q6, Q8): an asynchronous job queue for Python that uses Redis as its broker, with cron running inside the worker rather than in a separate scheduler process. Confirm that Celery is not also present.",
    "The worksheet does not say whether the browser calls FastAPI directly (arrows 4 and 5, drawn as primary) or through Next.js (dashed arrow 5b). Which pattern is in use decides where authentication is enforced, which container's logs show an API failure, and what the proxy has to route.",
    "The reverse proxy product (nginx, Caddy, Traefik, or other) is not named, and neither is whether it runs as a Compose service or on the host.",
    "Q18 says outbound HTTPS goes only to ttu.edu and depts.ttu.edu. Q42 (OpenAI) and Q74 (Twilio) require api.openai.com and api.twilio.com, and a full browser render fetches whatever the scanned pages embed. Treat the egress answer as unverified.",
    "Ports shown for Next.js (3000) and FastAPI (8000) are the tools' defaults, not documented values. PostgreSQL (5432) and Redis (6379) are standard. Anything marked (inference) comes from how these tools are normally deployed, not from the worksheet."
  ],
  cardFields: ["What it is", "Job in Compass", "Receives", "Produces", "Depends on", "If it goes down", "Not documented", "Blueprint module"],
  nodes: [
    { id: "B", concept: "client", here: "Q46: email and password sign-in with a session cookie; no SSO or MFA. Cookie flags and session lifetime are not documented. Ask where the session is stored and what the cookie flags are.", x: 40, y: 40, w: 210, h: 56, label: "Browser", sub: ["runs the React UI delivered by Next.js"],
      card: {
        "What it is": "The user's web browser running the Compass React interface.",
        "Job in Compass": "Renders the UI, holds the session cookie, sends API requests, polls for scan status.",
        "Receives": "HTML, JavaScript, and CSS from Next.js; JSON from FastAPI.",
        "Produces": "HTTPS requests carrying the session cookie.",
        "Depends on": "The reverse proxy being reachable on 443 with a valid certificate.",
        "If it goes down": "Nothing server-side changes. A running scan continues.",
        "Blueprint module": "6, The front end." } },
    { id: "RP", concept: "proxy", here: "Q51: TLS is terminated at a reverse proxy. The product, its location (container or host), the certificate source, and the renewal date are not documented. Ask for the config file path and the routing rules; they also settle Pattern A versus Pattern B.", x: 450, y: 60, w: 360, h: 60, label: "Reverse proxy", sub: ["TLS termination and path routing", "product not named in worksheet"],
      card: {
        "What it is": "A process that terminates TLS and forwards plain HTTP to internal services based on hostname or path. Q51 confirms it exists; the product is not named.",
        "Job in Compass": "The only listener exposed to the campus network. Routes UI traffic to Next.js and API traffic to FastAPI. Holds the certificate.",
        "Receives": "HTTPS from browsers on 443.",
        "Produces": "HTTP to web:3000 and api:8000 on the Compose network (inference).",
        "Depends on": "Certificate files, routing configuration, DNS (Domain Name System) for the hostname.",
        "If it goes down": "The whole application is unreachable. Background scans keep running.",
        "Not documented": "Product; whether it runs as a container or on the host; certificate source and renewal date; whether it is part of the Compose file (which decides whether a compose restart takes it down).",
        "Blueprint module": "9, Quality and delivery; 10, Operations." } },
    { id: "WEB", concept: "nextjs", here: "Q1: Next.js 16, React 19, TypeScript, Tailwind. Port 3000 is the tool's default, not a documented value. Whether pages fetch data on the server (Pattern B) or the browser calls FastAPI (Pattern A) is not documented; the rewrites in next.config.js answer it.", x: 340, y: 190, w: 250, h: 62, label: "Next.js 16 on Node.js", sub: ["web container", "port 3000, inference"],
      card: {
        "What it is": "Next.js is a framework for building React applications with a server side; Node.js is the JavaScript runtime it runs on. Version 16 uses the App Router.",
        "Job in Compass": "Serves the UI: page shell, compiled JavaScript bundles, CSS, and server-rendered pages. In Pattern B it also calls FastAPI.",
        "Receives": "HTTP GET requests from the reverse proxy.",
        "Produces": "HTML, JavaScript, CSS.",
        "Depends on": "A completed build inside its image; in Pattern B, FastAPI.",
        "If it goes down": "Users get 502 from the proxy. The API and scans continue. Users with a loaded page may keep working until they navigate.",
        "Not documented": "Whether pages fetch data on the server; the build output mode.",
        "Blueprint module": "6, The front end." } },
    { id: "API", concept: "fastapi", here: "Q2, Q7: FastAPI on Python 3.13 with async SQLAlchemy 2.0, session-cookie auth, a JSON API with OpenAPI docs. Not documented: session store and lifetime, cookie flags, CSRF and CORS settings, whether /docs is public, the password hashing algorithm.", x: 640, y: 190, w: 290, h: 62, label: "FastAPI on Python 3.13", sub: ["api container, port 8000, inference", "auth, roles, data access, enqueue"],
      card: {
        "What it is": "FastAPI is a Python web framework for JSON APIs. It runs under an ASGI (Asynchronous Server Gateway Interface) server, normally uvicorn (inference), and publishes its own OpenAPI documentation (Q7).",
        "Job in Compass": "Authentication (email and password, session cookie, Q46); authorization (admin and user roles, SiteAssignment, category visibility, Q47, Q50); every read and write to PostgreSQL made on behalf of a user; enqueueing jobs to Redis; the Ask AI call to OpenAI (Q40).",
        "Receives": "HTTP with JSON and the session cookie from the proxy (or from Next.js in Pattern B).",
        "Produces": "JSON responses; SQL to PostgreSQL; arq job records to Redis; HTTPS requests to OpenAI.",
        "Depends on": "PostgreSQL, Redis, and the .env values (database URL, Redis URL, OpenAI key and model name, a session signing secret (inference)).",
        "If it goes down": "Every UI action that touches data fails. Running scans continue, because the worker does not go through the API.",
        "Not documented": "Where sessions are stored (signed cookie, Redis, or PostgreSQL) and their lifetime; the password hashing algorithm; whether /docs and /openapi.json are reachable without login; CSRF protection.",
        "Blueprint module": "3, The API; 7, Identity and security." } },
    { id: "REDIS", concept: "redis", here: "Q6, Q8: one Redis shared by the app and the worker as the arq broker. Persistence mode, volume, password, and whether sessions or cache also live here are not documented.", x: 340, y: 320, w: 250, h: 56, label: "Redis", sub: ["arq job broker, port 6379"],
      card: {
        "What it is": "An in-memory key-value store, used here as the message broker for arq.",
        "Job in Compass": "Holds the arq queue (a sorted set of job ids), each job's record and arguments, job results (kept 3600 seconds by arq default), and the arq health-check key. It may also hold sessions or cache (not documented).",
        "Receives": "Enqueue commands from FastAPI; poll and claim commands from the worker.",
        "Produces": "Job records to the worker.",
        "Depends on": "Memory; a volume if persistence is expected.",
        "If it goes down": "Run scan fails at enqueue; the worker cannot pick up work; if sessions live here, everyone is signed out. If Redis restarts without persisted data, queued jobs disappear.",
        "Not documented": "Persistence mode (RDB snapshots, AOF, or none); volume; password; whether anything besides arq uses it.",
        "Blueprint module": "4, Jobs and the queue." } },
    { id: "PG", concept: "postgres", here: "Q3, Q9: PostgreSQL 16 with ten tables; schema by create_all() plus hand-written idempotent migrations, no Alembic; no encryption at rest (Q51). Volume location and when migrations run are not documented.", x: 640, y: 320, w: 290, h: 56, label: "PostgreSQL 16", sub: ["db container, port 5432"],
      card: {
        "What it is": "A relational database server.",
        "Job in Compass": "The system of record for Site, Scan, Page, Issue, SiteAssignment, User, PageValidation, PageChangeEvent, SiteRequest, and RunDiff (Q9), including review and ignore decisions with acting user and timestamp (Q37, Q57).",
        "Receives": "SQL over TCP 5432 from the api and worker containers.",
        "Produces": "Query results; the content of every backup.",
        "Depends on": "A persistent volume; the schema, created by SQLAlchemy create_all() plus hand-written idempotent migrations (Q3). SQLAlchemy is the ORM (Object-Relational Mapper) the Python code uses to talk to the database. Alembic, the usual migration tool for SQLAlchemy, is not used.",
        "If it goes down": "The API returns errors for everything. A running scan errors on its next write. Committed data survives if the volume does.",
        "Not documented": "Volume location; connection limits; when migrations run (at application start, inference); how the team knows which migrations have already been applied; encryption at rest (none, Q51).",
        "Blueprint module": "1, Data and Postgres; 2, Python and the ORM." } },
    { id: "CRON", concept: "arqcron", here: "Q29: a daily scheduled recrawl check with a per-site interval. Whether it is arq cron, host cron, or a loop is not documented, and neither is the container's time zone.", x: 340, y: 450, w: 250, h: 56, label: "arq cron schedule", sub: ["inside the worker, inference"],
      card: {
        "What it is": "arq's scheduling feature. Cron entries are declared in WorkerSettings and fire inside the worker process. Inference: this is how the daily check is implemented.",
        "Job in Compass": "The daily scheduled recrawl check with a per-site interval (Q29).",
        "Receives": "The clock and the per-site interval settings.",
        "Produces": "A job run inside the worker.",
        "Depends on": "The worker being up at the scheduled time.",
        "If it goes down": "It goes down with the worker. A missed slot is not caught up (arq behavior, inference).",
        "Not documented": "Whether it is arq cron, a host cron calling a script, or a loop inside the worker.",
        "Blueprint module": "4, Jobs and the queue." } },
    { id: "WORKER", concept: "arqworker", here: "Q6, Q19 to Q29: a single worker container runs the whole scan pipeline. The configured job_timeout and max_jobs, and whether api and worker share one image (Q13 describes one image of a few GB), are not documented.", x: 640, y: 450, w: 290, h: 62, label: "arq worker, Python", sub: ["worker container", "runs the scan pipeline"],
      card: {
        "What it is": "A Python process started from an arq WorkerSettings class. It polls Redis and runs job functions as coroutines, up to max_jobs at once (arq default 10), with a per-job timeout (arq default 300 seconds) and retries (arq default 5 tries).",
        "Job in Compass": "The entire scan pipeline (Q19 to Q29): discovery, rendering, axe-core, screenshots, content hashing, LanguageTool checks, PDF checks, scoring, RunDiff, PageChangeEvent, and the scheduled recrawl check. Sends content-change summaries to OpenAI and SMS via Twilio (inference on which process).",
        "Receives": "Job records from Redis; Site configuration from PostgreSQL; page content from TTU sites.",
        "Produces": "Page, Issue, and related rows; screenshot files; Scan status and score; the backup trigger; external API calls.",
        "Depends on": "Redis, PostgreSQL, Chromium, LanguageTool's Java process, Node for Lighthouse, disk for screenshots, outbound network.",
        "If it goes down": "Scans queue and never start; scheduled checks do not run; nothing alerts (Q68). A scan that was mid-run stays at whatever status it last wrote.",
        "Not documented": "Configured job_timeout and max_jobs; whether one worker process runs all jobs (Q6 says a single worker); whether api and worker share one image (Q13 describes one image).",
        "Blueprint module": "4, Jobs and the queue; 5, The crawl engine." } },
    { id: "PW", concept: "playwright", here: "Q4, Q21, Q24: Playwright with headless Chromium, a render pool of browser contexts, and a politeness delay. Pool size, per-page timeout, and the /dev/shm size are not documented.", x: 340, y: 590, w: 165, h: 62, label: "Playwright + Chromium", sub: ["headless, render pool", "inside worker container"],
      card: {
        "What it is": "Playwright is a browser automation library. The Python package ships a driver process that launches and controls Chromium, a full browser running without a window.",
        "Job in Compass": "Renders each page with JavaScript executed (Q25); follows links and reads sitemap.xml for discovery (Q19); honors robots.txt (Q23); takes screenshots; provides the page context axe-core runs in. Concurrency is bounded by the render pool of browser contexts (Q21) and a politeness delay (Q24).",
        "Receives": "Commands from the worker (navigate, wait, evaluate, screenshot).",
        "Produces": "The rendered DOM (Document Object Model, the live page structure), page text, screenshot bytes, final URL after redirects, HTTP status.",
        "Depends on": "Chromium's system libraries in the image; memory (each context can use hundreds of MB, inference); outbound HTTPS.",
        "If it goes down": "Pages error (Q28); the scan completes with gaps or fails. A Chromium crash can take the worker's memory with it.",
        "Not documented": "Render pool size; per-page timeout; whether /dev/shm is enlarged for Chromium in Docker (a common crash cause, inference).",
        "Blueprint module": "5, The crawl engine." } },
    { id: "AXE", concept: "axe", here: "Q5: axe-core against WCAG 2.2 A, AA, and AAA; results feed the check catalog and scoring config (Q34, Q35). No formal accuracy measurement exists (Q30, Q31).", x: 535, y: 590, w: 95, h: 62, label: "axe-core", sub: ["JS injected into", "each page"],
      card: {
        "What it is": "Deque's open-source accessibility rules engine, a JavaScript library that runs inside the page.",
        "Job in Compass": "Evaluates each rendered page against WCAG 2.2 rules at A, AA, and AAA (Q5). Its output feeds the check catalog and scoring config (Q34, Q35).",
        "Receives": "The live page, with the script injected by Playwright.",
        "Produces": "JSON with four buckets: violations, passes, incomplete (rules axe could not decide, the likely source of the manual-review flag in Q32, inference), and inapplicable. Each item carries a rule id, an impact level, WCAG tags, and the affected elements.",
        "Depends on": "Injection succeeding (a site's Content Security Policy can block it) and the axe-core version pinned in the image.",
        "If it goes down": "No findings for the page. A version change alters rule ids and results without any change to Compass code.",
        "Blueprint module": "5, The crawl engine." } },
    { id: "LT", concept: "languagetool", here: "Q8, Q13: listed as a dependency, with a JRE in the image. Which checks use it, how it starts, and its port are not documented.", x: 670, y: 590, w: 125, h: 62, label: "LanguageTool", sub: ["Java process", "JRE in image"],
      card: {
        "What it is": "An open-source grammar and spelling checker written in Java, usually run as a local HTTP server.",
        "Job in Compass": "Not stated beyond being a dependency (Q8, Q13). Inference: text-quality checks that feed the TTU-specific or manual-review checks.",
        "Receives": "Page text over local HTTP (inference).",
        "Produces": "A JSON list of matches.",
        "Depends on": "The JRE (Java Runtime Environment) in the image; memory (the Java process is large).",
        "If it goes down": "Whichever checks use it fail or are skipped. Whether the scan continues is not documented.",
        "Not documented": "Which checks use it; how it is started; its port.",
        "Blueprint module": "5, The crawl engine." } },
    { id: "LH", concept: "lighthouse", here: "Q13: bundled in the image with Node. Whether it runs at all and what it contributes are not documented.", x: 835, y: 590, w: 120, h: 62, label: "Lighthouse", sub: ["Node process", "use not documented"],
      card: {
        "What it is": "Google's page auditing tool, a Node program that drives Chrome and reports performance, accessibility, and other scores.",
        "Job in Compass": "Not documented; only listed as bundled in the image (Q13).",
        "Receives": "A URL (inference).",
        "Produces": "An audit JSON.",
        "Depends on": "Node in the image. It starts its own Chrome unless pointed at an existing one (inference).",
        "If it goes down": "Unknown until its use is known.",
        "Not documented": "Whether it runs at all, per page or per scan, and what it contributes to scoring.",
        "Blueprint module": "5, The crawl engine." } },
    { id: "PDF", concept: "pdfplumber", here: "Q26: documents are fetched separately and checked without screenshots. Which PDF checks exist is not documented.", x: 340, y: 710, w: 150, h: 56, label: "pdfplumber", sub: ["PDF text extraction"],
      card: {
        "What it is": "A Python library for extracting text, characters, and tables from PDFs.",
        "Job in Compass": "The PDF checks (Q26). Documents are fetched separately and checked without screenshots.",
        "Receives": "PDF bytes.",
        "Produces": "Text and layout data.",
        "Depends on": "Nothing external; runs inside the worker process.",
        "If it goes down": "PDF checks fail for that document.",
        "Not documented": "Which PDF checks exist. pdfplumber reads page content, not the PDF tag tree, so it cannot test tagging, reading order, or alternative text.",
        "Blueprint module": "5, The crawl engine." } },
    { id: "FS", concept: "files", here: "Q63: screenshots are files that need manual cleanup after a site is deleted. Path, size, growth (Q17), and backup inclusion are not documented.", x: 520, y: 710, w: 125, h: 62, label: "Screenshot files", sub: ["volume or host path", "not documented"],
      card: {
        "What it is": "Files on disk, either a Docker volume or a host path. Q63 describes files, not database rows.",
        "Job in Compass": "Page screenshots shown in the UI.",
        "Receives": "Image files from the worker.",
        "Produces": "Files read by FastAPI or served directly (not documented).",
        "Depends on": "Disk space; the mount surviving rebuilds.",
        "If it goes down": "Scans error on write; the UI shows missing images.",
        "Not documented": "Path; size; growth (Q17); whether backups include it (Q59 says database backups); whether the api container mounts the same path.",
        "Blueprint module": "1, Data and Postgres; 10, Operations." } },
    { id: "BK", concept: "backups", here: "Q59, Q60: a database backup after each scan, restore tested once; RTO and RPO undefined; destination and retention not documented.", x: 670, y: 710, w: 285, h: 62, label: "Database backup after each scan", sub: ["mechanism and location", "not documented"],
      card: {
        "What it is": "A dump of PostgreSQL taken after each new scan; restore has been tested (Q59).",
        "Job in Compass": "Recovery of scan data.",
        "Receives": "A trigger from the worker or a script after scan completion.",
        "Produces": "Dump files.",
        "Depends on": "pg_dump or similar (inference); disk; someone noticing failures.",
        "If it goes down": "No new restore points; nothing alerts.",
        "Not documented": "Mechanism; destination (same host or elsewhere); retention; whether screenshots and .env are included; RTO and RPO (Recovery Time Objective and Recovery Point Objective), which Q60 says are undefined.",
        "Blueprint module": "10, Operations." } },
    { id: "DC", concept: "compose", here: "Q11, Q16, Q12: one server, Docker Compose, one container per service, one environment for everything. The service list, restart policies, health checks, and log rotation are not documented.", x: 340, y: 830, w: 230, h: 62, label: "Docker Compose", sub: ["defines services, network,", "volumes"],
      card: {
        "What it is": "A tool that starts a set of containers from one YAML file and creates a private network where each service is reachable by its service name.",
        "Job in Compass": "Defines and starts web, api, worker, db, redis, and possibly proxy and languagetool services (Q16); wires ports, volumes, and environment.",
        "Receives": "The compose file and .env.",
        "Produces": "Running containers, a network, volumes.",
        "Depends on": "Docker Engine on the host.",
        "If it goes down": "It is not a running process. If Docker Engine stops, every service stops.",
        "Not documented": "The service list; restart policies; health checks; resource limits; log rotation.",
        "Blueprint module": "9, Quality and delivery." } },
    { id: "ENV", concept: "env", here: "Q52: a server-side .env read by Compose, not in source control. The variable list, file permissions, and who has SSH are not documented.", x: 610, y: 830, w: 200, h: 62, label: ".env file on the host", sub: ["secrets and configuration"],
      card: {
        "What it is": "A plain text file of KEY=value lines on the host, read by Docker Compose (Q52), not in source control.",
        "Job in Compass": "All secrets and environment-specific settings.",
        "Receives": "Edits by the developer over SSH.",
        "Produces": "Environment variables inside containers.",
        "Depends on": "Host file permissions.",
        "If it goes down": "Containers start with missing settings and fail on first use.",
        "Not documented": "The variable list. Inference from the stack: database URL and password, Redis URL, OpenAI API key and model name (Q44), session signing secret, Twilio credentials, base URL, render pool and timeout settings.",
        "Blueprint module": "7, Identity and security; 9, Quality and delivery." } },
    { id: "TTU", concept: "targets", here: "Q18, Q23, Q27: ttu.edu and depts.ttu.edu, public pages only, robots.txt honored, standard browser user agent. Q18's egress answer omits OpenAI and Twilio and whatever the pages embed.", x: 1000, y: 580, w: 160, h: 62, label: "TTU websites", sub: ["ttu.edu, depts.ttu.edu"],
      card: {
        "What it is": "The sites being scanned, published through Modern Campus (OmniUpdate).",
        "Job in Compass": "The input.",
        "Receives": "HTTPS GET requests from Chromium and the PDF fetcher, with a standard browser user agent (Q23).",
        "Produces": "HTML, assets, PDFs, and the footer 'last updated' stamp Compass reads for change detection (Q73).",
        "Depends on": "Campus web infrastructure.",
