      ["openssl s_client -connect HOST:443 -servername HOST </dev/null 2>/dev/null | openssl x509 -noout -dates -subject", "certificate subject and expiry from the outside"],
      ["the proxy's access and error logs", "every request with status code and upstream time; 502 and 504 entries are the first place to look for outages"]
