    terms: [["TLS termination", "the proxy decrypts HTTPS and talks plain HTTP to the backends"], ["Upstream", "a backend the proxy forwards to"], ["502 versus 504", "502: the backend refused or answered badly; 504: the backend did not answer in time"], ["X-Forwarded-For", "the original client address, passed to the backend by the proxy"], ["HSTS", "a header telling browsers to use HTTPS only"]],
