      ["docker compose exec worker python -c 'import playwright; print(playwright.__version__)'", "the Playwright version; Chromium is pinned to it"],
      ["docker compose logs worker | grep -i -E 'timeout|target closed|crashed'", "page-level failures from the browser"],
      ["docker stats --no-stream", "memory growth while a scan runs"],
      ["docker compose config | grep -n -E 'shm_size|mem_limit|memory'", "whether memory and shared memory are set at all"]
    ],
    terms: [["Headless", "a browser running without a window"], ["Browser context", "an isolated session inside one browser; the unit the render pool counts"], ["DOM", "the live tree of the rendered page"], ["CDP", "Chrome DevTools Protocol, the wire the driver uses"], ["Politeness delay", "a pause between requests to the same site"], ["User agent", "the identity string the browser sends; crawlers should be identifiable"]],
    resources: [
