    terms: [["Logical backup", "a dump of SQL or rows (pg_dump); physical backup copies data files and WAL"], ["RPO", "how much data loss is acceptable, which sets frequency"], ["RTO", "how long recovery may take, which sets the procedure"], ["Off-host", "stored on another machine or service"], ["Restore test", "actually restoring, on a schedule"]],
