 op.create_index(\"ix_jobs_status\", \"jobs\", [\"status\"])\n\ndef downgrade():\n    op.drop_table(\"results\")\n    op.drop_table(\"jobs\")\n    op.drop_table(\"users\")"}]}, {"path": "api/Dockerfile", "desc": "The API image. No secrets inside; everything arrives as environment variables.", "regions": [{"tags": ["API", "ENV", "REPO", "22", "d6"], "code": "FROM python:3.13-slim\nWORKDIR /srv\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\nCOPY app ./app\nCOPY alembic.ini .\nCOPY alembic ./alembic\nCMD [\"uvicorn\", \"app.main:app\", \"--host\", \"0.0.0.0\", \"--port\", \"8000\"]"}]}, {"path": "worker/worker.py", "desc": "The job function, the cron entries, and the arq contract. Every job must be safe to run twice.", "regions": [{"tags": ["WORKER", "9"], "code": "# Helpers not shown: discover(ctx, target), notify(job_id), select_due_targets(session).\nimport asyncio\nimport os\nfrom datetime import datetime, timedelta, timezone\nfrom arq import cron\nfrom arq.connections import RedisSettings\nfrom sqlalchemy import update\nfrom sqlalchemy.dialects.postgresql import insert\nfrom playwright.async_api import async_playwright\nfrom app.db import SessionLocal                 # the same models and settings as the API\nfrom app.models import Job, Result\nfrom app.settings import settings\n\ndef now():\n    return datetime.now(timezone.utc)"}, {"tags": ["WORKER", "RT", "11", "d9"], "code": "async def startup(ctx):\n    # One browser per worker process, shared by every job; the semaphore is the render pool.\n    ctx[\"pw\"] = await async_playwright().start()\n    ctx[\"browser\"] = await ctx[\"pw\"].chromium.launch(headless=True, args=[\"--disable-dev-shm-usage\"])\n    ctx[\"pool\"] = asyncio.Semaphore(int(os.environ.get(\"RENDER_POOL\", \"3\")))   # sized by memory\n\nasync def shutdown(ctx):\n    await ctx[\"browser\"].close()\n    await ctx[\"pw\"].stop()"}, {"tags": ["WORKER", "RT", "X2", "11", "12"], "code": "async def render(ctx, url: str):\n    context = await ctx[\"browser\"].new_context(user_agent=\"ExampleScanner/1.0 (+https://example.org/scanner)\")\n    try:\n        page = await context.new_page()\n        await page.goto(url, timeout=30_000, wait_until=\"networkidle\")   # a full render fetches everything the page embeds\n        data = {\"title\": await page.title(), \"final_url\": page.url}\n        png = await page.screenshot(full_page=True)\n        return data, png\n    finally:\n        await context.close()                                            # memory comes back here"}, {"tags": ["WORKER", "FILES", "13"], "code": "def save_file(job_id: int, key: str, png: bytes) -> str:\n    path = f\"/data/files/{job_id}/{abs(hash(key))}.png\"                  # on the files volume\n    os.makedirs(os.path.dirname(path), exist_ok=True)\n    with open(path, \"wb\") as f:\n        f.write(png)\n    return path                                                          # the row keeps this"}, {"tags": ["WORKER", "PG", "10", "d3"], "code": "async def set_status(job_id: int, status: str, error: str | None = None):\n    async with SessionLocal() as s:\n        await s.execute(update(Job).where(Job.id == job_id)\n                        .values(status=status, error=error, finished_at=now() if status in (\"succeeded\", \"failed\") else None))\n        await s.commit()\n\nasync def upsert_result(s, job_id: int, key: str, data: dict, path: str):\n    stmt = insert(Result).values(job_id=job_id, item_key=key, payload=data, file_path=path)\n    await s.execute(stmt.on_conflict_do_update(index_elements=[\"job_id\", \"item_key\"],\n                                                set_={\"payload\": data, \"file_path\": path}))   # retry-safe"}, {"tags": ["WORKER", "REDIS", "PG", "RT", "FILES", "X1", "X2", "9", "10", "11", "12", "13", "14", "d3"], "code": "async def run_job(ctx, job_id: int):\n    async with SessionLocal() as s:\n        job = await s.get(Job, job_id)\n        if job is None or job.status == \"succeeded\":\n            return                                                       # a retry of finished work is a no-op\n        job.status, job.started_at, job.heartbeat_at = \"running\", now(), now()\n        await s.commit()\n        target = job.target\n    try:\n        urls = await discover(ctx, target)                               # read the target system\n        for i, url in enumerate(urls):\n            async with ctx[\"pool\"]:                                      # at most RENDER_POOL pages at once\n                data, png = await render(ctx, url)\n            path = save_file(job_id, url, png)\n            async with SessionLocal() as s:\n                await upsert_result(s, job_id, url, data, path)\n                await s.execute(update(Job).where(Job.id == job_id)\n                                .values(progress=int(100 * (i + 1) / len(urls)), heartbeat_at=now()))\n                await s.commit()                                         # progress the client can poll\n            await asyncio.sleep(settings.politeness_delay_seconds)\n        await notify(job_id)                                             # external call from the worker\n        await set_status(job_id, \"succeeded\")\n    except Exception as exc:\n        await set_status(job_id, \"failed\", str(exc)[:500])               # failed, with a message a user can read\n        raise                                                            # arq counts the try; max_tries decides"}, {"tags": ["CRON", "WORKER", "PG", "16", "d3"], "code": "async def sweeper(ctx):\n    # A dead worker leaves rows at running. Without a heartbeat for longer than\n    # job_timeout, the row is marked failed instead of looking alive forever.\n    cutoff = now() - timedelta(seconds=settings.job_timeout_seconds + 300)\n    async with SessionLocal() as s:\n        await s.execute(update(Job).where(Job.status == \"running\", Job.heartbeat_at < cutoff)\n                        .values(status=\"failed\", error=\"no heartbeat; the worker died\"))\n        await s.commit()\n\nasync def scheduled_check(ctx):\n    # The daily job. It enqueues run_job for whatever is due; the job id keeps it to one run per day.\n    async with SessionLocal() as s:\n        due = await select_due_targets(s)\n    for target_id in due:\n        await ctx[\"redis\"].enqueue_job(\"run_job\", target_id, _job_id=f\"daily-{target_id}-{now():%Y%m%d}\")"}, {"tags": ["WORKER", "CRON", "REDIS", "9", "16", "d3", "d9"], "code": "class WorkerSettings:\n    functions = [run_job]\n    cron_jobs = [cron(sweeper, minute={0, 15, 30, 45}),\n                 cron(scheduled_check, hour=2, minute=0)]        # 02:00 on the container's clock; set TZ\n    on_startup = startup\n    on_shutdown = shutdown\n    redis_settings = RedisSettings.from_dsn(settings.redis_url)\n    max_jobs = int(os.environ.get(\"MAX_JOBS\", \"4\"))                # concurrency per process\n    job_timeout = settings.job_timeout_seconds                     # above the longest expected job\n    max_tries = 3                                                  # after that the job is marked failed by arq\n    keep_result = 3600\n    health_check_interval = 60                                     # refreshes arq:queue:health-check in Redis"}]}, {"path": "worker/Dockerfile", "desc": "The worker image: the API code plus the heavy runtimes. Build context is the project root.", "regions": [{"tags": ["WORKER", "RT", "REPO", "22", "d6", "d9"], "code": "FROM mcr.microsoft.com/playwright/python:v1.55.0-noble   # Chromium and its libraries are included\nWORKDIR /srv\nCOPY api/requirements.txt api-requirements.txt\nCOPY worker/requirements.txt worker-requirements.txt\nRUN pip install --no-cache-dir -r api-requirements.txt -r worker-requirements.txt\nCOPY api/app ./app                                        # same models and settings as the API\nCOPY worker/worker.py .\nCMD [\"arq\", \"worker.WorkerSettings\"]"}]}, {"path": "web/app/jobs/page.tsx", "desc": "The client side of the job pattern: one POST, then polling until the status is final.", "regions": [{"tags": ["WEB", "C", "3"], "code": "\"use client\";                                     // this component runs in the browser\nimport { useEffect, useState } from \"react\";\n\ntype JobView = { id: number; status: string; progress: number; error?: string };\n\nexport default function JobsPage() {\n  const [job, setJob] = useState<JobView | null>(null);"}, {"tags": ["C", "RP", "API", "1", "4", "8", "d3"], "code": "  async function start() {\n    // The browser attaches the session cookie itself; the proxy routes /api to FastAPI.\n    const r = await fetch(\"/api/jobs\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ kind: \"scan\", target: \"https://example.org\" }),\n    });\n    if (r.status === 401) { location.href = \"/login\"; return; }\n    setJob(await r.json());                       // the id comes back at once\n  }"}, {"tags": ["C", "RP", "API", "17", "4", "d3"], "code": "  useEffect(() => {\n    if (!job || job.status === \"succeeded\" || job.status === \"failed\") return;\n    const t = setInterval(async () => {           // poll every 3 s until the status is final\n      const r = await fetch(`/api/jobs/${job.id}`);\n      if (r.ok) setJob(await r.json());\n    }, 3000);\n    return () => clearInterval(t);\n  }, [job]);"}, {"tags": ["WEB", "C", "3"], "code": "  return (\n    <main>\n      <button onClick={start}>Run</button>\n      {job && <p>Job {job.id}: {job.status} {job.progress}% {job.error}</p>}\n    </main>\n  );\n}"}]}, {"path": "web/next.config.js", "desc": "Pattern A needs no rewrites: the proxy already routes /api. Pattern B would call API_INTERNAL_URL from server code.", "regions": [{"tags": ["WEB", "4b", "d1"], "code": "/** @type {import('next').NextConfig} */\nmodule.exports = {\n  output: \"standalone\",          // a self-contained server for the image\n  // Pattern B example: fetch(`${process.env.API_INTERNAL_URL}/jobs`, { headers: { cookie } }) in a server component,\n  // forwarding the cookie by hand. Pick one pattern as the rule and document the exceptions.\n};"}]}, {"path": "web/Dockerfile", "desc": "Build once, run the standalone server. Public build-time values are baked in here.", "regions": [{"tags": ["WEB", "REPO", "22", "d6"], "code": "FROM node:22-alpine AS build\nWORKDIR /srv\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\nRUN npm run build                # NEXT_PUBLIC_* values are compiled in now, not read at start\n\nFROM node:22-alpine\nWORKDIR /srv\nCOPY --from=build /srv/.next/standalone ./\nCOPY --from=build /srv/.next/static ./.next/static\nEXPOSE 3000\nCMD [\"node\", \"server.js\"]"}]}, {"path": "ops/deploy.sh", "desc": "Run on the host by a person or a pipeline. Deploy by tag; rollback is the previous tag.", "regions": [{"tags": ["OPS", "REPO", "DC", "22", "23", "d6"], "code": "#!/usr/bin/env bash\nset -euo pipefail\ncd /srv/app\nTAG=\"${1:?usage: deploy.sh <git tag>}\"\ngit fetch --tags\ngit checkout \"$TAG\"                                       # what is running is now readable from git\ndocker compose build --pull"}, {"tags": ["OPS", "PG", "DC", "23", "d4", "d6"], "code": "docker compose run --rm api alembic upgrade head          # migrations before the new API starts\ndocker compose up -d --remove-orphans                     # replaces containers; volumes survive\ndocker compose ps\necho \"deployed $TAG at $(date -Is)\" >> /srv/app/deploys.log"}]}, {"path": "ops/backup.sh", "desc": "Nightly from host cron. A backup is a restore that has not happened yet; test it.", "regions": [{"tags": ["BK", "PG", "FILES", "19a", "19b", "d4"], "code": "#!/usr/bin/env bash\nset -euo pipefail\nset -a; source /srv/app/.env; set +a                      # POSTGRES_USER and POSTGRES_DB\nSTAMP=$(date +%F-%H%M)\nDEST=/backup/local\nREMOTE=backup@offsite.example.org:/srv/backups/app\ndocker compose -f /srv/app/compose.yaml exec -T db \\\n  pg_dump -U \"$POSTGRES_USER\" -Fc \"$POSTGRES_DB\" > \"$DEST/db-$STAMP.dump\"     # consistent while running\ndocker run --rm -v app_files:/data:ro -v \"$DEST\":/out alpine \\\n  tar czf \"/out/files-$STAMP.tgz\" -C /data .                                 # the files volume too\nrsync -a \"$DEST/\" \"$REMOTE/\"                                                 # off the host\nfind \"$DEST\" -type f -mtime +14 -delete                                      # retention"}, {"tags": ["BK", "LOGS", "d7"], "code": "echo \"backup ok $STAMP\"                                                      # the line a monitor watches for"}]}, {"path": "ops/daemon.json", "desc": "/etc/docker/daemon.json on the host. Docker does not rotate container logs unless told to.", "regions": [{"tags": ["LOGS", "DC", "20a", "20b", "20c", "d7"], "code": "{\n  \"log-driver\": \"json-file\",\n  \"log-opts\": { \"max-size\": \"20m\", \"max-file\": \"5\" }\n}"}]}, {"path": "ci/azure-pipelines.yml", "desc": "Runs on every push: test, build images tagged with the commit, push to a registry.", "regions": [{"tags": ["REPO", "OPS", "22", "d6", "d8"], "code": "trigger: [main]\npool: { vmImage: ubuntu-latest }\nsteps:\n  - script: pip install -r api/requirements.txt && pytest api/tests\n    displayName: Test\n  - script: |\n      docker build -t registry.example.org/app-api:$(Build.SourceVersion) api\n      docker build -t registry.example.org/app-worker:$(Build.SourceVersion) -f worker/Dockerfile .\n      docker build -t registry.example.org/app-web:$(Build.SourceVersion) web\n    displayName: Build images tagged with the commit\n  - script: |\n      docker push registry.example.org/app-api:$(Build.SourceVersion)\n      docker push registry.example.org/app-worker:$(Build.SourceVersion)\n      docker push registry.example.org/app-web:$(Build.SourceVersion)\n    displayName: Push"}]}];

